<script setup lang="ts">
import { ref } from 'vue'
import { outfitRoleOptions, type OutfitElement, type OutfitLayerMove } from '../../domain/outfit'
import { cropPatch, clamp } from './board-geometry'
import AuthImage from '../AuthImage.vue'
const props = defineProps<{ items: OutfitElement[]; canForward: boolean; canBackward: boolean }>()
const emit = defineEmits<{ (e: 'patch', patch: Partial<OutfitElement>): void; (e: 'scale', factor: number): void; (e: 'rotate', angle: number, relative: boolean): void; (e: 'offset', x: number, y: number): void; (e: 'layer', direction: OutfitLayerMove): void; (e: 'flip'): void; (e: 'duplicate'): void; (e: 'replace'): void; (e: 'remove'): void; (e: 'info'): void }>()
const angle = ref(0), percent = ref(100), dx = ref(0), dy = ref(0)
function resize(value: number | string) { const item = props.items[0], width = clamp(Number(value), 24, 2160); emit('patch', { width, ...(!item.freeStretch ? { height: clamp(item.height * width / item.width, 24, 2700) } : {}) }) }
function crop(axis: 'x' | 'y' | 'width' | 'height', value: number | string) { emit('patch', cropPatch(props.items[0], axis, Number(value))) }
</script>
<template><view><view v-if="items.length > 1"><view class="sheet-head">已选中 {{ items.length }} 张贴纸</view><text class="line small">画板上可整体拖动、双指缩放；以下属性应用到每张选中贴纸，可一次撤销。</text><view class="field"><text class="field-label">统一旋转角度</text><wd-input-number v-model="angle" :min="0" :max="360" /><view class="actions section"><wd-button size="small" @click="emit('rotate', angle, false)">应用角度</wd-button><wd-button size="small" plain @click="emit('rotate', -15, true)">各自 −15°</wd-button><wd-button size="small" plain @click="emit('rotate', 15, true)">各自 +15°</wd-button></view></view><view class="field"><text class="field-label">各自等比缩放（%）</text><wd-input-number v-model="percent" :min="10" :max="500" /><wd-button size="small" @click="emit('scale', percent / 100)">应用缩放</wd-button></view><view class="field"><text class="field-label">整体平移</text><view class="actions"><text>X</text><wd-input-number v-model="dx" :min="-1080" :max="1080" /><text>Y</text><wd-input-number v-model="dy" :min="-1350" :max="1350" /></view><wd-button size="small" @click="emit('offset', dx, dy)">应用偏移</wd-button></view><view class="actions section"><wd-button size="small" plain @click="emit('flip')">各自水平翻转</wd-button><wd-button size="small" plain @click="emit('patch', { freeStretch: true })">开启自由拉伸</wd-button><wd-button size="small" plain @click="emit('patch', { freeStretch: false })">恢复等比缩放</wd-button></view></view>
  <template v-else-if="items[0]"><view class="sheet-head">贴纸属性</view><view class="row"><view class="thumb"><AuthImage :src="items[0].assetUrl" :width="320" /></view><view class="row-body"><text class="title">{{ items[0].garmentLabel }}</text><view class="tags"><wd-tag plain>{{ items[0].kind === 'PERSON_PART' ? '人物贴纸' : '衣物贴纸' }}</wd-tag></view><wd-button v-if="items[0].kind !== 'PERSON_PART'" type="text" size="small" @click="emit('info')">查看衣物信息</wd-button></view></view><view v-if="items[0].garmentStatus === 'TRASHED' || items[0].garmentChanged" class="notice warning">{{ items[0].garmentStatus === 'TRASHED' ? '衣物已在回收站，画板仍保留原图片。' : '衣物已有更新，画板仍保留原图片。' }}</view><wd-tag v-if="['INPUT', 'GENERATE'].includes(items[0].assetKind)" type="warning">当前素材带背景</wd-tag>
    <wd-picker v-if="items[0].kind !== 'PERSON_PART'" :model-value="items[0].role" :columns="outfitRoleOptions" label="画板分组" @confirm="emit('patch', { role: $event.value })" />
    <view class="field"><text class="field-label">{{ items[0].freeStretch ? '宽度（自由拉伸）' : '大小（等比缩放）' }}</text><wd-input-number :model-value="Math.round(items[0].width)" :min="24" :max="2160" :step="10" @update:model-value="resize" /></view><view class="field spread"><text>自由拉伸</text><wd-switch :model-value="!!items[0].freeStretch" @update:model-value="emit('patch', { freeStretch: !!$event })" /></view><text class="small">开启后可分别调整宽高</text><view v-if="items[0].freeStretch" class="field"><text class="field-label">高度</text><wd-input-number :model-value="Math.round(items[0].height)" :min="24" :max="2700" :step="10" @update:model-value="emit('patch', { height: Number($event) })" /></view><view class="field"><text class="field-label">旋转角度（°）</text><wd-input-number :model-value="Math.round(items[0].rotation)" :min="-360" :max="360" :step="15" @update:model-value="emit('rotate', Number($event), false)" /><wd-slider :model-value="Math.round(items[0].rotation)" :min="0" :max="360" @change="emit('rotate', Number($event.value), false)" /></view>
    <view class="actions section"><wd-button size="small" plain @click="emit('flip')">水平翻转</wd-button><wd-button size="small" plain @click="emit('duplicate')">复制贴纸</wd-button></view><view class="field"><text class="field-label">裁剪范围（百分比）</text><view class="crop"><view><text>X</text><wd-input-number :model-value="Math.round(items[0].cropX * 100)" :min="0" :max="99" @update:model-value="crop('x', $event)" /></view><view><text>Y</text><wd-input-number :model-value="Math.round(items[0].cropY * 100)" :min="0" :max="99" @update:model-value="crop('y', $event)" /></view><view><text>宽</text><wd-input-number :model-value="Math.round(items[0].cropWidth * 100)" :min="1" :max="100" @update:model-value="crop('width', $event)" /></view><view><text>高</text><wd-input-number :model-value="Math.round(items[0].cropHeight * 100)" :min="1" :max="100" @update:model-value="crop('height', $event)" /></view></view><wd-button type="text" @click="emit('patch', { cropX: 0, cropY: 0, cropWidth: 1, cropHeight: 1 })">恢复完整图片</wd-button></view>
    <view class="field"><text class="field-label">位置</text><view class="crop"><view><text>X</text><wd-input-number :model-value="Math.round(items[0].x)" :min="0" :max="1080" @update:model-value="emit('patch', { x: Number($event) })" /></view><view><text>Y</text><wd-input-number :model-value="Math.round(items[0].y)" :min="0" :max="1350" @update:model-value="emit('patch', { y: Number($event) })" /></view></view></view><view class="field"><text class="field-label">前后层级</text><view class="actions"><wd-button size="small" plain :disabled="!canForward" @click="emit('layer', 'forward')">前移一层</wd-button><wd-button size="small" plain :disabled="!canBackward" @click="emit('layer', 'backward')">后移一层</wd-button><wd-button size="small" plain :disabled="!canForward" @click="emit('layer', 'front')">置于顶层</wd-button><wd-button size="small" plain :disabled="!canBackward" @click="emit('layer', 'back')">置于底层</wd-button></view></view><wd-button v-if="items[0].kind !== 'PERSON_PART'" block plain :disabled="items[0].garmentStatus === 'TRASHED'" @click="emit('replace')">替换衣物</wd-button>
  </template><view v-if="items.length" class="section"><wd-button block type="error" plain @click="emit('remove')">{{ items.length > 1 ? '删除所选' : '从搭配移除' }}</wd-button></view><wd-status-tip v-else image="content" tip="选中贴纸后调整属性" /></view></template>
<style lang="scss" scoped>@import './outfit.scss';.crop{display:flex;flex-direction:column;gap:20rpx}.crop>view{display:flex;align-items:center;justify-content:space-between;gap:16rpx}</style>
